#!/usr/bin/perl
# Read-only: print raw windows around each regex match in a file.
# usage: win.pl FILE BEFORE AFTER MAXHITS REGEX
use strict;
my ($f,$b,$a,$max,$re)=@ARGV;
open(my $fh,'<:raw',$f) or die; local $/; my $s=<$fh>; close $fh;
my $n=0;
while ($s =~ /$re/gi) {
  my $st=$-[0]; my $en=$+[0];
  my $from=$st-$b; $from=0 if $from<0;
  print "--- hit ",++$n," at $st\n", substr($s,$from,$en-$from+$a), "\n";
  last if $n>=$max;
}
my $c=()= $s =~ /$re/gi; print "TOTAL=$c\n";

