#!/usr/bin/perl
# Read-only: print windows around each match in a file, for human reading.
# usage: win.pl FILE BEFORE AFTER MAXHITS PHRASE
# Spaces in PHRASE match any run of whitespace/tags/nbsp in the raw HTML.
# Output window is shown with tags removed and common entities read, display only.
use strict;
my ($f,$b,$a,$max,$ph)=@ARGV;
open(my $fh,'<:raw',$f) or die; local $/; my $s=<$fh>; close $fh;
my $gap='(?:\s|<[^>]*>|&#160;|&nbsp;)+';
my $re=join($gap, map { $_ } split / /, $ph);
my $n=0; my $raw=0;
my $lit=quotemeta($ph);
my $rawc=()= $s =~ /$lit/gi;
while ($s =~ /$re/gi) {
  my $st=$-[0]; my $en=$+[0];
  my $from=$st-$b; $from=0 if $from<0;
  my $w=substr($s,$from,$en-$from+$a);
  $w=~s/<[^>]*>/ /g; $w=~s/&#8217;/\x{2019}/g; $w=~s/&#8220;/\x{201c}/g; $w=~s/&#8221;/\x{201d}/g;
  $w=~s/&#8212;/\x{2014}/g; $w=~s/&#8211;/\x{2013}/g; $w=~s/&#160;|&nbsp;/ /g; $w=~s/&amp;/&/g; $w=~s/\s+/ /g;
  binmode STDOUT,':utf8';
  print "--- hit ",++$n," at $st (raw span ",$en-$st," bytes)\n$w\n";
  last if $n>=$max;
}
my $c=()= $s =~ /$re/gi; print "TOTAL(flex)=$c  TOTAL(literal raw)=$rawc\n";

